55	// recordOptionPatchProblems は問題 1 つの options・option_patches・chosen_option を検査する。plans は同じ回の
56	// 修正計画で、covered_by の参照先を解決するのに使う。
57	//
58	// options の書き方を検査するのは、判断待ち (awaiting-human) の問題と、option_patches を持つ問題だけ。
59	// 過去の記録の pending・done・not-fixed には自由な書き方の options が残っており、記録の過去の回は
60	// 書き換えないため。判断待ちの問題は、古い記録でも報告する (review-triage-fix で再開して人間が回答すれば、
61	// パッチが作られて検査を通る)。
62	func recordOptionPatchProblems(pl recordPlan, plans []recordPlan) []string {
63		var problems []string
64		add := func(format string, args ...any) {
65			problems = append(problems, fmt.Sprintf(format, args...))
66		}
67		awaiting := pl.Status == "awaiting-human"
68		if !awaiting && len(pl.OptionPatches) == 0 && pl.ChosenOption == "" {
69			return nil
70		}
71	
72		// options の行。空の options は、判断待ちなら状態の検査が報告するので、ここでは重ねない。
73		labels := map[string]bool{}
74		var labelOrder []string
75		for _, line := range recordOptionLines(pl.Options) {
76			if line.label == "" {
77				add("options の %d 行目がラベルで始まっていません (行の先頭に案のラベル (例: A・B・H1) を書き、後に半角空白か ( か : を続ける): %q", line.no, recordCell(line.text))
78				continue
79			}
80			if labels[line.label] {
81				add("options にラベル %q の行が 2 つあります (人間がどちらの案を選んだかが決まらない)", line.label)
82				continue
83			}
84			labels[line.label] = true
85			labelOrder = append(labelOrder, line.label)
86		}
87	
88		// option_patches の要素。
89		byOption := map[string]recordOptionPatch{}
90		for i, op := range pl.OptionPatches {
91			en := fmt.Sprintf("option_patches[%d]", i)
92			if op.Option == "" {
93				add("%s: option がありません (案のラベルを書く)", en)
94			} else {
95				if !labels[op.Option] {
96					add("%s: option %q は options のどの行の先頭にもありません", en, op.Option)
97				}
98				if _, dup := byOption[op.Option]; dup {
99					add("option_patches に option %q の要素が 2 つあります (どちらのパッチを当てるかが決まらない)", op.Option)
100				} else {
101					byOption[op.Option] = op
102				}
103			}
104			kinds := 0
105			if op.Patch != "" {
106				kinds++
107			}
108			if op.NoChange != nil {
109				kinds++
110				if !*op.NoChange {
111					add("%s: no_change は true だけを書く (ファイルを変える案なら patch を書く)", en)
112				}
113			}
114			if op.CoveredBy != nil {
115				kinds++
116			}
117			if kinds != 1 {
118				add("%s: patch・no_change・covered_by のどれか 1 つだけを書く (2 つ以上か、どれも無い)", en)
119			}
120			if op.Patch != "" {
121				if op.Base == "" {
122					add("%s: patch があるのに base がありません (パッチを作ったときの HEAD の短縮 SHA)", en)
123				}
124				if !strings.HasPrefix(op.Patch, "diff --git") {
125					add("%s: patch が diff --git で始まっていません (git diff の出力をそのまま書く)", en)
126				}
127				if !strings.HasSuffix(op.Patch, "\n") {
128					add("%s: patch の末尾に改行がありません (git apply が末尾の改行を要る。YAML のブロックは |- ではなく | で書く)", en)
129				}
130			} else if op.Base != "" {
131				add("%s: patch が無い要素に base があります (base は patch があるときだけ書く)", en)
132			}
133			if ref := op.CoveredBy; ref != nil {
134				for _, m := range recordPatchRefProblems(pl.ProblemID, *ref, plans) {
135					add("%s: %s", en, m)
136				}
137			}
138		}
139	
140		// 判断待ちの問題は、options のすべての案にパッチ (かファイルを変えないこと・覆う参照) が要る。
141		if awaiting {
142			for _, label := range labelOrder {
143				if _, ok := byOption[label]; !ok {
144					add("判断待ち (awaiting-human) なのに、案 %q の要素が option_patches にありません (案ごとにパッチを作る。ファイルを変えない案は no_change: true)", label)
145				}
146			}
147		}
148	
149		// 人間が選んだ案。
150		if c := pl.ChosenOption; c != "" {
151			op, ok := byOption[c]
152			if !ok {
153				add("chosen_option %q は option_patches のどの要素の option でもありません", c)
154			}
155			if awaiting {
156				// 残っていると、人間がまだ見ていない作り直したパッチについて、選んだ案があるように読める。
157				add("判断待ち (awaiting-human) に chosen_option があります (パッチを作り直して判断待ちに戻すときは消す)")
158			} else if ok && pl.Status == "pending" && op.NoChange != nil && *op.NoChange {
159				add("status pending なのに、chosen_option %q はファイルを変えない案 (no_change) です (修正フェーズが当てるパッチが無い。直さないなら status: not-fixed にする)", c)
160			} else if ok && pl.Status == "not-fixed" && (op.NoChange == nil || !*op.NoChange) {
161				add("status not-fixed なのに、chosen_option %q はファイルを変える案です (決めないと回答したときに選べるのは、ファイルを変えない案 (no_change) だけ)", c)
162			}
163			// 1 つの修正で覆う問題は、同じ回答で参照先の案も選ぶ (SKILL.md の手順 1 の「人間の回答の反映」)。
164			// 参照先が選んでいないと、修正フェーズは人間がまだ選んでいない参照先の変更をコミットする。
165			if ok && (pl.Status == "pending" || pl.Status == "done") && op.CoveredBy != nil {
166				ref := *op.CoveredBy
167				for _, other := range plans {
168					if other.ProblemID == ref.ProblemID && other.ProblemID != pl.ProblemID && other.ChosenOption != ref.Option {
169						add("chosen_option %q は %s の案 %q のパッチで覆う案なのに、%s の chosen_option が %q です (1 つの修正で覆う問題は、同じ回答で参照先の案も選ぶ)",
170							c, ref.ProblemID, ref.Option, ref.ProblemID, other.ChosenOption)
171					}
172				}
173			}
174		} else if (pl.Status == "pending" || pl.Status == "done") && len(pl.OptionPatches) > 0 {
175			// 案を選んで pending にした問題は、修正フェーズが chosen_option の案のパッチを当てる (SKILL.md の手順 1 の
176			// 「人間の回答の反映」)。無いと、人間が見たパッチを当てずに approach の文から直すことになる。
177			add("status %s で option_patches があるのに、chosen_option がありません (人間が選んだ案のラベルを書く。修正フェーズは、その案のパッチを当てる)", pl.Status)
178		}
179		return problems
180	}
