182	// recordPatchRefProblems は covered_by の参照を検査する。参照先は、同じ回の、ほかの問題の、パッチを持つ要素。
183	func recordPatchRefProblems(self string, ref recordPatchRef, plans []recordPlan) []string {
184		var problems []string
185		if ref.ProblemID == "" {
186			problems = append(problems, "covered_by.problem_id がありません")
187		}
188		if ref.Option == "" {
189			problems = append(problems, "covered_by.option がありません")
190		}
191		if ref.ProblemID == "" || ref.Option == "" {
192			return problems
193		}
194		if ref.ProblemID == self {
195			return append(problems, "covered_by が自分の問題を指しています (覆うのはほかの問題の案のパッチ)")
196		}
197		for _, other := range plans {
198			if other.ProblemID != ref.ProblemID {
199				continue
200			}
201			for _, op := range other.OptionPatches {
202				if op.Option != ref.Option {
203					continue
204				}
205				if op.Patch == "" {
206					problems = append(problems, fmt.Sprintf("covered_by が指す %s の案 %q は、パッチを持つ要素ではありません", ref.ProblemID, ref.Option))
207				}
208				return problems
209			}
210			return append(problems, fmt.Sprintf("covered_by の案 %q は、問題 %s の option_patches にありません", ref.Option, ref.ProblemID))
211		}
212		return append(problems, fmt.Sprintf("covered_by の問題 %q は同じ回の plans にありません", ref.ProblemID))
213	}
214	
215	// renderOptionPatches は option_patches を持つ問題の小節「#### <問題> の案」を書く。要素ごとに、options の
216	// 該当の行と、パッチ (diff のコードブロック)・ファイルを変えないこと・覆う参照のどれかを出す。
217	// option_patches の無い問題には何も書かない。無い記録の出力が変わると、既存のサマリがすべて古いと報告されるため。
218	func renderOptionPatches(b *strings.Builder, pl recordPlan) {
219		if len(pl.OptionPatches) == 0 {
220			return
221		}
222		fmt.Fprintf(b, "\n#### %s の案\n", recordCell(pl.ProblemID))
223		if pl.ChosenOption != "" {
224			fmt.Fprintf(b, "\n選んだ案: %s\n", recordCell(pl.ChosenOption))
225		}
226		lines := recordOptionLines(pl.Options)
227		for _, op := range pl.OptionPatches {
228			// 案の行。options に無いラベル (検査が報告する) は、ラベルだけを出す。
229			text := op.Option
230			for _, line := range lines {
231				if line.label != "" && line.label == op.Option {
232					text = line.text
233					break
234				}
235			}
236			fmt.Fprintf(b, "\n%s\n", recordCell(text))
237			switch {
238			case op.Patch != "":
239				fence := strings.Repeat("`", max(3, recordLongestBacktickRun(op.Patch)+1))
240				patch := op.Patch
241				if !strings.HasSuffix(patch, "\n") {
242					patch += "\n"
243				}
244				fmt.Fprintf(b, "\nパッチ (起点 `%s`):\n\n%sdiff\n%s%s\n", recordCell(op.Base), fence, patch, fence)
245			case op.NoChange != nil && *op.NoChange:
246				b.WriteString("\nファイルを変えない。\n")
247			case op.CoveredBy != nil:
248				fmt.Fprintf(b, "\n%s の案 %s のパッチで覆う。\n", recordCell(op.CoveredBy.ProblemID), recordCell(op.CoveredBy.Option))
249			}
250		}
251	}
252	
253	// recordLongestBacktickRun は s の中で最も長く続くバッククォートの数を返す。
254	func recordLongestBacktickRun(s string) int {
255		longest, run := 0, 0
256		for _, r := range s {
257			if r == '`' {
258				run++
259				if run > longest {
260					longest = run
261				}
262			} else {
263				run = 0
264			}
265		}
266		return longest
267	}
