39	// recordOptionLines は options の空でない行を返す。
40	func recordOptionLines(options string) []recordOptionLine {
41		var lines []recordOptionLine
42		for i, line := range strings.Split(options, "\n") {
43			if strings.TrimSpace(line) == "" {
44				continue
45			}
46			label := ""
47			if m := recordOptionLabelRe.FindStringSubmatch(line); m != nil {
48				label = m[1]
49			}
50			lines = append(lines, recordOptionLine{no: i + 1, label: label, text: line})
51		}
52		return lines
53	}
54	
55	// recordOptionPatchProblems は問題 1 つの options・option_patches・chosen_option を検査する。plans は同じ回の
56	// 修正計画で、covered_by の参照先を解決するのに使う。
57	//
58	// options の書き方を検査するのは、判断待ち (awaiting-human) の問題と、option_patches を持つ問題だけ。
59	// 過去の記録の pending・done・not-fixed には自由な書き方の options が残っており、記録の過去の回は
