182	// recordPatchRefProblems は covered_by の参照を検査する。参照先は、同じ回の、ほかの問題の、パッチを持つ要素。
183	func recordPatchRefProblems(self string, ref recordPatchRef, plans []recordPlan) []string {
184		var problems []string
185		if ref.ProblemID == "" {
186			problems = append(problems, "covered_by.problem_id がありません")
187		}
188		if ref.Option == "" {
189			problems = append(problems, "covered_by.option がありません")
190		}
191		if ref.ProblemID == "" || ref.Option == "" {
192			return problems
193		}
194		if ref.ProblemID == self {
195			return append(problems, "covered_by が自分の問題を指しています (覆うのはほかの問題の案のパッチ)")
196		}
197		for _, other := range plans {
198			if other.ProblemID != ref.ProblemID {
199				continue
200			}
201			for _, op := range other.OptionPatches {
202				if op.Option != ref.Option {
203					continue
204				}
205				if op.Patch == "" {
206					problems = append(problems, fmt.Sprintf("covered_by が指す %s の案 %q は、パッチを持つ要素ではありません", ref.ProblemID, ref.Option))
207				}
208				return problems
209			}
210			return append(problems, fmt.Sprintf("covered_by の案 %q は、問題 %s の option_patches にありません", ref.Option, ref.ProblemID))
211		}
212		return append(problems, fmt.Sprintf("covered_by の問題 %q は同じ回の plans にありません", ref.ProblemID))
213	}
