216	// 該当の行と、パッチ (diff のコードブロック)・ファイルを変えないこと・覆う参照のどれかを出す。
217	// option_patches の無い問題には何も書かない。無い記録の出力が変わると、既存のサマリがすべて古いと報告されるため。
218	func renderOptionPatches(b *strings.Builder, pl recordPlan) {
219		if len(pl.OptionPatches) == 0 {
220			return
221		}
222		fmt.Fprintf(b, "\n#### %s の案\n", recordCell(pl.ProblemID))
223		if pl.ChosenOption != "" {
224			fmt.Fprintf(b, "\n選んだ案: %s\n", recordCell(pl.ChosenOption))
225		}
226		lines := recordOptionLines(pl.Options)
227		for _, op := range pl.OptionPatches {
228			// 案の行。options に無いラベル (検査が報告する) は、ラベルだけを出す。
229			text := op.Option
230			for _, line := range lines {
231				if line.label != "" && line.label == op.Option {
232					text = line.text
233					break
234				}
235			}
236			fmt.Fprintf(b, "\n%s\n", recordCell(text))
237			switch {
238			case op.Patch != "":
239				fence := strings.Repeat("`", max(3, recordLongestBacktickRun(op.Patch)+1))
240				patch := op.Patch
241				if !strings.HasSuffix(patch, "\n") {
242					patch += "\n"
243				}
244				fmt.Fprintf(b, "\nパッチ (起点 `%s`):\n\n%sdiff\n%s%s\n", recordCell(op.Base), fence, patch, fence)
245			case op.NoChange != nil && *op.NoChange:
246				b.WriteString("\nファイルを変えない。\n")
247			case op.CoveredBy != nil:
248				fmt.Fprintf(b, "\n%s の案 %s のパッチで覆う。\n", recordCell(op.CoveredBy.ProblemID), recordCell(op.CoveredBy.Option))
249			}
250		}
251	}
