253	// recordLongestBacktickRun は s の中で最も長く続くバッククォートの数を返す。
254	func recordLongestBacktickRun(s string) int {
255		longest, run := 0, 0
256		for _, r := range s {
257			if r == '`' {
258				run++
259				if run > longest {
260					longest = run
261				}
262			} else {
263				run = 0
264			}
265		}
266		return longest
267	}
